-- Holster Your Shield v1.0 for Steam build 26088801. Generated by scripts/build.py from src/bingus_runtime.lua, src/bingus_memory.lua, src/holster_your_shield.lua; edit those.
if rawget(_G, 'HolsterYourShieldInstalled') then return end
local bingus_runtime = (function()
-- bingus_runtime.lua, version 1: the core of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_runtime.lua.
--
-- Helldivers 2 runs the game and every Lua mod in one LuaJIT state, with one
-- global update chain. This file gives a mod the update guard every mod used
-- to write by hand, and the session table all runtime copies share. It uses no
-- FFI and no system function.
--
-- Loading: each runtime file is one chunk that returns a table and installs
-- nothing until the mod asks. A mod vendors byte-identical copies of the files
-- it needs and runs each once when it loads:
--   local runtime = <bingus_runtime.lua>              -- this file: shared(), guard()
--   local memory = <bingus_memory.lua>.new(runtime)   -- reads, page checks, module hashes, time()
--   <bingus_write.lua>.extend(memory)                 -- checked writes, added to memory
-- A mod that never touches memory vendors this file alone; one that only reads
-- vendors this file and bingus_memory.lua.
--
-- Copies of different versions can run in the same game. Their session state
-- lives in one global table, BingusRuntime = {hashes, statuses, versions,
-- hash_reads}, which every copy of every version shares.
--
-- runtime.shared([globals]) -> BingusRuntime, created or repaired.
-- runtime.guard(options) -> guard: the update and shutdown wrappers. The
-- previous update runs outside pcall, so its errors reach the game unchanged
-- (P1); the first failure survives shutdown as "stopped after: <reason>" (P2);
-- 8 errors stop the mod, counted per burst so rare transient errors never add
-- up (P3); a mod that can restore its state pauses after an error below it and
-- resumes when the updates below run cleanly again; every argument and return
-- value passes through; a status table per mod lands in BingusRuntime.statuses.
--
-- Per-frame cost of a guard: the mod's step under pcall, a few boolean tests
-- and stores and two integer counters around the previous update; no
-- allocation, closure or system call. Unmeasured in game.
local runtime = {VERSION = 1}

local type, pcall, error, tostring, rawget, rawset, ipairs = type, pcall, error, tostring, rawget, rawset, ipairs

-- Session state shared by every copy of every version ----------------------------

local SHARED = 'BingusRuntime'
local SHARED_TABLES = {'hashes', 'statuses', 'versions'}

-- Another copy, another version or another mod may have left the table
-- incomplete (even `BingusRuntime = {}`): missing or broken fields are filled in,
-- so one stray assignment cannot stop every mod on the runtime.
function runtime.shared(globals)
    globals = globals or _G
    local shared = rawget(globals, SHARED)
    if type(shared) ~= 'table' then
        shared = {}
        rawset(globals, SHARED, shared)
    end
    for _, field in ipairs(SHARED_TABLES) do
        if type(rawget(shared, field)) ~= 'table' then rawset(shared, field, {}) end
    end
    if type(rawget(shared, 'hash_reads')) ~= 'number' then rawset(shared, 'hash_reads', 0) end
    rawset(rawget(shared, 'versions'), runtime.VERSION, true)
    return shared
end

-- Update guard -----------------------------------------------------------------------

-- options:
--   name    key in BingusRuntime.statuses (required, one guard per name)
--   step    function(dt, ...) before the previous update, every frame while running
--   after   function() after the previous update returned, while running
--   stop    function(reason) once, when the guard stops or the game shuts down;
--           its errors are kept in status.stop_error, never raised
--   pause   function(reason), optional: an update below this mod raised; restore
--           the game state and reset the mod to a fresh start. With it the guard
--           pauses (no step, no after) and resumes once the updates below have
--           returned on `resume` frames in a row (default 60). Without it such an
--           error stops the guard. A pause that raises stops the guard.
--   log     function(line) for the guard's few lines (errors, pauses, resumes, stop)
--   errors  errors that stop the guard (default 8), counted separately for the
--           mod's own step and after and for the updates below it. A count starts
--           again after `clean` frames without such an error (default 3600, about a
--           minute at 60 FPS), so rare transient errors never add up to a stop.
--   env     the table holding update and shutdown (default _G)
-- guard.install() wraps env.update and env.shutdown and returns the guard.
-- guard.stop(reason) stops it from the mod (a refusal counts as the first failure).
-- guard.running() is true from install until a stop or shutdown.
-- guard.status: {name, version, state, installed, errors, lower_errors, pauses,
--   first_error, burst_error, first_failure, stop_error}; state is 'new', 'running',
--   'paused: <reason>', 'stopped: <reason>', then at shutdown 'stopped' or
--   'stopped after: <first failure>'.
function runtime.guard(options)
    local name = options.name
    if type(name) ~= 'string' or name == '' then error('guard name required', 0) end
    local shared = runtime.shared(options.env)
    if shared.statuses[name] and shared.statuses[name].installed then error('guard ' .. name .. ' already installed', 0) end
    local status = {name = name, version = runtime.VERSION, state = 'new', installed = false, errors = 0,
        lower_errors = 0, pauses = 0}
    shared.statuses[name] = status
    local step, after_step, stop_work, pause_work, log = options.step, options.after, options.stop, options.pause,
        options.log
    local limit, resume_after, clean_after = options.errors or 8, options.resume or 60, options.clean or 3600
    local previous_update, previous_shutdown
    local in_previous, stopped, paused, failed = false, false, false, false
    local clean_run, lower_run = 0, 0

    local function note(line)
        if log then pcall(log, line) end
    end

    local function halt(reason)
        if stopped then return end
        stopped, paused = true, false
        status.first_failure = status.first_failure or reason
        status.state = 'stopped: ' .. reason
        note(name .. ' stopped: ' .. reason)
        if stop_work then
            local ok, why = pcall(stop_work, reason)
            if not ok then status.stop_error = tostring(why) end
        end
    end

    -- The mod's own step or after raised: one log line per burst of errors.
    local function failed_step(problem)
        failed, clean_run = true, 0
        status.errors = status.errors + 1
        local text = tostring(problem)
        status.first_error = status.first_error or text
        if status.errors == 1 then
            status.burst_error = text
            note(name .. ' error: ' .. text)
        end
        if status.errors >= limit then halt('stopped after ' .. limit .. ' errors: ' .. status.burst_error) end
    end

    -- An update below this mod raised (seen on the next frame).
    local function failed_below()
        lower_run = 0
        status.lower_errors = status.lower_errors + 1
        if not pause_work then return halt('the previous update failed') end
        if status.lower_errors >= limit then
            return halt('stopped after ' .. limit .. ' failed updates below this mod')
        end
        if paused then return end
        paused = true
        status.pauses = status.pauses + 1
        status.state = 'paused: the previous update failed'
        note(name .. ' paused: the previous update failed')
        local ok, why = pcall(pause_work, 'the previous update failed')
        if not ok then halt('pause failed: ' .. tostring(why)) end
    end

    local function resume_when_clean()
        if paused and lower_run >= resume_after then
            paused = false
            status.state = 'running'
            note(name .. ' resumed after ' .. resume_after .. ' clean frames')
        end
    end

    -- Counts a frame without an own error, which also clears an old burst.
    local function count_clean()
        if failed then return end
        clean_run = clean_run + 1
        if clean_run == clean_after then status.errors = 0 end
    end

    local function finish(...)
        in_previous = false
        lower_run = lower_run + 1
        if lower_run == clean_after then status.lower_errors = 0 end
        if not stopped and not paused then
            if after_step then
                local ok, problem = pcall(after_step)
                if not ok then failed_step(problem) end
            end
            count_clean()
        end
        return ...
    end

    -- The previous update runs outside pcall: its errors (value and traceback)
    -- reach the game unchanged. One that raised leaves in_previous set, and the
    -- next frame pauses (or stops) this mod and keeps forwarding.
    local function update(...)
        failed = false
        if in_previous then
            in_previous = false
            if not stopped then failed_below() end
        end
        resume_when_clean()
        if step and not stopped and not paused then
            local ok, problem = pcall(step, ...)
            if not ok then failed_step(problem) end
        end
        in_previous = true
        return finish(previous_update(...))
    end

    local function shutdown(...)
        if in_previous then
            in_previous = false
            status.first_failure = status.first_failure or 'the previous update failed'
        end
        local failure = status.first_failure
        if not stopped then
            stopped = true
            if stop_work then
                local ok, why = pcall(stop_work, 'shutdown')
                if not ok then status.stop_error = tostring(why) end
            end
        end
        status.state = failure and ('stopped after: ' .. failure) or 'stopped'
        if previous_shutdown then return previous_shutdown(...) end
    end

    local guard = {status = status}

    function guard.install()
        local env = options.env or _G
        if status.installed then error('guard ' .. name .. ' already installed', 0) end
        previous_update = rawget(env, 'update')
        if type(previous_update) ~= 'function' then error('game update unavailable', 0) end
        previous_shutdown = rawget(env, 'shutdown')
        rawset(env, 'update', update)
        rawset(env, 'shutdown', shutdown)
        status.installed, status.state = true, 'running'
        return guard
    end

    function guard.stop(reason)
        halt(tostring(reason))
    end

    function guard.running()
        return status.installed and not stopped
    end

    return guard
end

return runtime
end)()
local bingus_memory = (function()
-- bingus_memory.lua, version 1: the read side of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_memory.lua.
--
-- Loading: the chunk returns {VERSION = 1, new = function(runtime)} and
-- installs nothing. A mod vendors a byte-identical copy next to
-- bingus_runtime.lua and runs each file once when it loads:
--   local runtime = <bingus_runtime.lua>
--   local memory = <bingus_memory.lua>.new(runtime)   -- the api below
--   <bingus_write.lua>.extend(memory)                 -- optional: checked writes
-- This file only reads memory, page information and module files; it never
-- changes memory or page protection. A mod whose build refuses sources that can
-- modify memory vendors bingus_runtime.lua and this file only.
--
-- Windows functions are declared under private, versioned FFI names
-- (bingus_memory1_*, each with an __asm__ label naming the real export), at
-- most once per version in the whole game. ffi.cdef keeps the first prototype
-- of a name for the whole game, so a plain name would bind to whatever another
-- mod declared first. Copies of other versions declare their own names.
--
-- memory.new(runtime) -> api. runtime is the table bingus_runtime.lua returns:
-- its shared table keeps module hashes for the session. Each api has its own
-- buffers and counters; every api of one copy shares the bound functions.
--   api.read(address, size)        the bytes as a string, or nil when they cannot
--                                  all be read; allocates only that string
--   api.read_into(address, size, buffer)  into a buffer the caller keeps: true or
--                                  false, no allocation
--   api.pointer(bytes [, offset])  the user-mode pointer stored little-endian at
--                                  bytes[offset+1 .. offset+8], as uint8_t *, or nil
--   api.address(pointer)           a pointer, number or integer cdata as a Lua number
--   api.distance(a, b)             api.address(a) - api.address(b)
--   api.writable_data(address, size)  true when [address, address + size) is
--                                  committed private read-write memory: never code,
--                                  read-only, guard or module image pages
--   api.queries                    page queries made so far (one per memory region)
--   api.time()                     seconds from the performance counter (a Lua number)
--   api.module([name])             a loaded module's base as uint8_t *, or nil;
--                                  no name: the executable
--   api.module_hash(module)        SHA-256 (uppercase hex) of the module's file, read
--                                  once per session for every mod (BingusRuntime.hashes)
--   api.verify_build(build)        build = {exe_sha256, game_sha256}: true, or false and why
--   api.windows                    {ffi, kernel32, bcrypt}: the bound functions under
--                                  their Windows names, for calls the api does not cover
-- Addresses are pointer cdata (read, read_into) or pointers, numbers and integer
-- cdata (address, distance, writable_data).
--
-- Cost per call: read and read_into one ReadProcessMemory (about 1-2 us in game);
-- writable_data one VirtualQuery per memory region in the range (about 0.29 ms
-- each in game), so check only on frames that act; time() one
-- QueryPerformanceCounter (unmeasured in game). read_into, address, distance,
-- writable_data and time allocate nothing, interpreted or compiled.
local memory = {VERSION = 1}

local type, error, pcall, tonumber, ipairs, pairs = type, error, pcall, tonumber, ipairs, pairs
local max, format, concat = math.max, string.format, table.concat

local HIGH = 4294967296
local MEM_COMMIT, MEM_PRIVATE, PAGE_READWRITE = 0x1000, 0x20000, 4

-- Windows functions ----------------------------------------------------------------

-- The region record is MEMORY_BASIC_INFORMATION with each 64-bit field read as
-- two 32-bit halves, and the cell turns a pointer into two halves through one
-- union (one base, so compiled code sees the store): neither allocates when read.
-- The region record is also this file's sentinel: once it exists, every
-- declaration below exists too.
local PREFIX = 'bingus_memory1_'
local SENTINEL = 'bingus_memory1_region'
local DECLARATIONS = [[
    typedef struct bingus_memory1_region {
        uint32_t base_low, base_high, allocation_base_low, allocation_base_high;
        uint32_t allocation_protection; uint16_t partition, reserved;
        uint32_t size_low, size_high, state, protection, type, padding;
    } bingus_memory1_region;
    typedef union bingus_memory1_cell {
        const void *pointer;
        struct { uint32_t low, high; };
    } bingus_memory1_cell;
    void *bingus_memory1_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
    uint32_t bingus_memory1_GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity) __asm__("GetModuleFileNameW");
    void *bingus_memory1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
    int bingus_memory1_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                         size_t *done) __asm__("ReadProcessMemory");
    uint32_t bingus_memory1_VirtualQuery(uint64_t address, bingus_memory1_region *region, size_t size) __asm__("VirtualQuery");
    int bingus_memory1_QueryPerformanceCounter(uint32_t *count) __asm__("QueryPerformanceCounter");
    int bingus_memory1_QueryPerformanceFrequency(uint32_t *frequency) __asm__("QueryPerformanceFrequency");
    void *bingus_memory1_CreateFileW(const uint16_t *path, uint32_t access, uint32_t share, void *security,
                                     uint32_t disposition, uint32_t flags, void *template_file) __asm__("CreateFileW");
    int bingus_memory1_ReadFile(void *file, void *buffer, uint32_t size, uint32_t *done, void *overlapped) __asm__("ReadFile");
    int bingus_memory1_CloseHandle(void *handle) __asm__("CloseHandle");
    int32_t bingus_memory1_BCryptOpenAlgorithmProvider(void **algorithm, const uint16_t *name, const uint16_t *provider,
                                                       uint32_t flags) __asm__("BCryptOpenAlgorithmProvider");
    int32_t bingus_memory1_BCryptCloseAlgorithmProvider(void *algorithm, uint32_t flags) __asm__("BCryptCloseAlgorithmProvider");
    int32_t bingus_memory1_BCryptCreateHash(void *algorithm, void **hash, void *object, uint32_t object_size,
                                            const void *secret, uint32_t secret_size, uint32_t flags) __asm__("BCryptCreateHash");
    int32_t bingus_memory1_BCryptHashData(void *hash, const void *data, uint32_t size, uint32_t flags) __asm__("BCryptHashData");
    int32_t bingus_memory1_BCryptFinishHash(void *hash, void *digest, uint32_t size, uint32_t flags) __asm__("BCryptFinishHash");
    int32_t bingus_memory1_BCryptDestroyHash(void *hash) __asm__("BCryptDestroyHash");
]]
local FUNCTIONS = {
    kernel32 = {'GetModuleHandleA', 'GetModuleFileNameW', 'GetCurrentProcess', 'ReadProcessMemory', 'VirtualQuery',
                'QueryPerformanceCounter', 'QueryPerformanceFrequency', 'CreateFileW', 'ReadFile', 'CloseHandle'},
    bcrypt = {'BCryptOpenAlgorithmProvider', 'BCryptCloseAlgorithmProvider', 'BCryptCreateHash',
              'BCryptHashData', 'BCryptFinishHash', 'BCryptDestroyHash'},
}

local bound, ticks_per_second
-- {ffi, kernel32, bcrypt}, each library table holding the functions above under
-- their Windows names. Declared at most once per version in the whole game.
local function bind()
    if bound then return bound end
    local ffi = require('ffi')
    if not ffi.abi('64bit') then error('Windows x64 is required', 0) end
    if not pcall(ffi.typeof, SENTINEL) then ffi.cdef(DECLARATIONS) end
    local result = {ffi = ffi}
    for library, names in pairs(FUNCTIONS) do
        local loaded, functions = ffi.load(library), {}
        for _, name in ipairs(names) do functions[name] = loaded[PREFIX .. name] end
        result[library] = functions
    end
    local frequency = ffi.new('uint32_t[2]')
    if result.kernel32.QueryPerformanceFrequency(frequency) == 0 then error('performance counter unavailable', 0) end
    ticks_per_second = frequency[0] + frequency[1] * HIGH
    bound = result
    return bound
end

-- Module files ---------------------------------------------------------------------

-- SHA-256 (uppercase hex) of the file at path (a UTF-16 string buffer).
local function sha256(windows, path)
    local ffi, kernel, bcrypt = windows.ffi, windows.kernel32, windows.bcrypt
    local file = kernel.CreateFileW(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
    if file == ffi.cast('void *', -1) then error('cannot read the module file', 0) end
    local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
    local ok, result = pcall(function()
        local id = ffi.new('uint16_t[7]', {83, 72, 65, 50, 53, 54, 0})  -- "SHA256"
        if bcrypt.BCryptOpenAlgorithmProvider(algorithm, id, nil, 0) ~= 0 then error('SHA-256 unavailable', 0) end
        if bcrypt.BCryptCreateHash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            error('SHA-256 unavailable', 0)
        end
        local buffer, count = ffi.new('uint8_t[1048576]'), ffi.new('uint32_t[1]')
        while true do
            if kernel.ReadFile(file, buffer, 1048576, count, nil) == 0 then error('module file read failed', 0) end
            if count[0] == 0 then break end
            if bcrypt.BCryptHashData(hash[0], buffer, count[0], 0) ~= 0 then error('SHA-256 failed', 0) end
        end
        local digest, hex = ffi.new('uint8_t[32]'), {}
        if bcrypt.BCryptFinishHash(hash[0], digest, 32, 0) ~= 0 then error('SHA-256 failed', 0) end
        for i = 0, 31 do hex[i + 1] = format('%02X', digest[i]) end
        return concat(hex)
    end)
    if hash[0] ~= nil then bcrypt.BCryptDestroyHash(hash[0]) end
    if algorithm[0] ~= nil then bcrypt.BCryptCloseAlgorithmProvider(algorithm[0], 0) end
    kernel.CloseHandle(file)
    if not ok then error(result, 0) end
    return result
end

-- The SHA-256 of a loaded module's file, read once per session for every mod:
-- kept in the shared table by file path.
local function module_hash(runtime, windows, module)
    local ffi = windows.ffi
    local path = ffi.new('uint16_t[32768]')
    local length = windows.kernel32.GetModuleFileNameW(module, path, 32768)
    if length == 0 or length >= 32768 then error('module file name unavailable', 0) end
    local shared = runtime.shared()
    local key = 'sha256:' .. ffi.string(path, length * 2)
    local cached = shared.hashes[key]
    if cached then return cached end
    local hex = sha256(windows, path)
    shared.hash_reads = shared.hash_reads + 1
    shared.hashes[key] = hex
    return hex
end

-- The api --------------------------------------------------------------------------

function memory.new(runtime)
    if type(runtime) ~= 'table' or type(runtime.shared) ~= 'function' then
        error('bingus_memory.lua: new(runtime) needs the table bingus_runtime.lua returns', 2)
    end
    runtime.shared()
    local windows = bind()
    local ffi, kernel = windows.ffi, windows.kernel32
    local read_memory, query, query_counter = kernel.ReadProcessMemory, kernel.VirtualQuery,
        kernel.QueryPerformanceCounter
    local process = kernel.GetCurrentProcess()
    -- ReadProcessMemory reports its count as a 64-bit size: it is read back as two
    -- 32-bit words, because reading the 64-bit value boxes a new cdata in
    -- interpreted code. Only the call writes this buffer.
    local done = ffi.new('size_t[1]')
    local done32 = ffi.cast('uint32_t *', done)
    local region, region_size = ffi.new(SENTINEL), ffi.sizeof(SENTINEL)
    local cell, counter = ffi.new('bingus_memory1_cell'), ffi.new('uint32_t[2]')
    local scratch_size = 256
    local scratch = ffi.new('uint8_t[?]', scratch_size)
    local ticks = ticks_per_second
    local api = {queries = 0, windows = windows}

    -- A pointer, number or integer cdata as a number, without allocating: a
    -- pointer passes through the cell. Exact below 2^53 (user-mode addresses
    -- end at 2^47).
    local function address_of(address)
        if type(address) == 'number' then return address end
        if type(address) == 'cdata' then
            local integer = tonumber(address)
            if integer then return integer end
        end
        cell.pointer = address
        return cell.low + cell.high * HIGH
    end

    function api.module(name)
        local handle = kernel.GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end

    -- The bytes at address as a string, or nil when they cannot all be read.
    -- Allocates only the returned string.
    function api.read(address, size)
        if size > scratch_size then
            scratch_size = max(size, scratch_size * 2)
            scratch = ffi.new('uint8_t[?]', scratch_size)
        end
        if read_memory(process, address, scratch, size, done) == 0 or done32[0] ~= size then
            return nil
        end
        return ffi.string(scratch, size)
    end

    -- Into a buffer the caller keeps: no allocation at all.
    function api.read_into(address, size, buffer)
        return read_memory(process, address, buffer, size, done) ~= 0 and done32[0] == size
    end

    -- The user-mode pointer stored little-endian at bytes[offset+1 .. offset+8].
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local b1, b2, b3, b4, b5, b6, b7, b8 = bytes:byte(offset + 1, offset + 8)
        if b7 ~= 0 or b8 ~= 0 then return nil end
        local value = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216 + (b5 + b6 * 256) * HIGH
        if value < 0x10000 or value >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value)
    end

    api.address = address_of

    function api.distance(first, second)
        return address_of(first) - address_of(second)
    end

    -- True when [address, address + size) is committed private read-write memory:
    -- never code, read-only, guard or module image pages. One VirtualQuery per
    -- region, each answered in the region record (no allocation).
    function api.writable_data(address, size)
        if type(size) ~= 'number' or size <= 0 then return false end
        local cursor = address_of(address)
        local finish = cursor + size
        while cursor < finish do
            api.queries = api.queries + 1
            if query(cursor, region, region_size) ~= region_size then return false end
            if region.state ~= MEM_COMMIT or region.type ~= MEM_PRIVATE or region.protection ~= PAGE_READWRITE then
                return false
            end
            local region_end = region.base_low + region.base_high * HIGH + region.size_low + region.size_high * HIGH
            if region_end <= cursor then return false end
            cursor = region_end
        end
        return true
    end

    -- Seconds since an arbitrary start (boot), from the performance counter read
    -- as two 32-bit halves into a reused buffer; the frequency is read once.
    function api.time()
        query_counter(counter)
        return (counter[0] + counter[1] * HIGH) / ticks
    end

    function api.module_hash(module)
        return module_hash(runtime, windows, module)
    end

    -- build: {exe_sha256, game_sha256}. true, or false and why.
    function api.verify_build(build)
        local exe, game = api.module(nil), api.module('game.dll')
        if not exe or not game then return false, 'game modules unavailable' end
        if api.module_hash(exe) ~= build.exe_sha256 or api.module_hash(game) ~= build.game_sha256 then
            return false, 'unsupported game build'
        end
        return true
    end

    return api
end

return memory
end)()
local Holster = (function()
-- Holster Your Shield v1.0 for Helldivers 2 Steam build 26088801 (port of the 25480438 release).
--
-- With a one-handed weapon in hand the game puts a shield backpack (the SH-20 Ballistic Shield or the SH-51
-- Directional Shield: equipment type 25) into the left hand. The shield in hand is the Helldiver's "held
-- carryable" in carry mode 2 (inventory row +20 and +32); on the back nothing is held. The game moves it with two
-- calls, 0x9ABC30 (the held carryable) and 0x9AC8E0 (the carry mode), and tells the other players with
-- rpc_set_held_carryable (0xBE20B0). Switching to a two-handed weapon stows it that way (0xA95910), wielding a
-- one-handed weapon draws it that way (0xA95A90).
--
-- This addon makes the same calls when the player presses Backpack Function (Avatar action 37, after rebinding
-- and controller processing) while wearing a shield backpack:
--   - shield in hand: it goes on the back, and stays there: when the game draws it again (a weapon switch, a
--     dropped objective, the re-wield after an action), the addon stows it again on the next frame;
--   - pressed again: it comes back to the hand if the weapon in hand is one-handed and nothing else is held
--     (the game's own conditions); otherwise the game draws it at the next one-handed wield.
-- It writes no memory. Other backpacks, other players' Helldivers and every other shield are left alone.
--
-- Cost per frame, while the game runs: one read of the local Helldiver's inventory row (24 bytes), plus one read
-- of action 37's held time while a shield backpack is worn. Every 30th frame about 6 more reads check that the
-- kept addresses still belong to the local Helldiver. A press or a re-stow first finds everything again from the
-- game's registries (about 25 reads), then makes the three calls. No page query, no write, no allocation per
-- frame.
local Holster = {VERSION = '1.0-26088801'}
Holster.REVISION = 'v' .. Holster.VERSION

local ffi = require('ffi')
local bit = require('bit')
local band, format = bit.band, string.format

Holster.GAME_SHA256 = '6D1D4D3BC6FC84801D9F8F1B310E13A603D07409F3D9495D74B42E1D0BB1C08F'
Holster.EXE_SHA256 = '0ACC07DEBE04714AE04281E1A66BD2EB9D3D85232953E32A93C8A3DD0874EABE'

-- Build 26088801 (remapped from build 25480438; evidence: native-work/megapack-port/HolsterYourShield/MAP.json).
Holster.LAYOUT = {
    players = 0x2CE1618,   -- player manager: +0x84 counts, +0xE8 local player record, +0x3A8 avatar network id
    owner = 0x2CE41B8,     -- entities: network-id map +0xF24990, entity-id map +0xF1C978, records +0xF349E0
    avatars = 0x2CE1EE0,   -- avatar manager: map +0xF8, count +0x6C, entity pointers +0x110, input slots +0x150
    inventory = 0x2CE18E8, -- map +40 by avatar entity id, identity pointers +64, 48-byte rows +80
    equipment = 0x2CE1F88, -- per-entity EquipmentComponent copies: map +80, 232-byte records at +144
    none_item = 0x2E3F0FC, -- the game's "nothing held" id (0 in this build)
    none_slot = 0x2E3F10C, -- the id 0xA95A90 compares an empty held carryable with (0 in this build)
    set_item = 0x9BD850,   -- (inventory, avatar entity, item): sets the held carryable
    set_mode = 0x9BE500,   -- (inventory, avatar entity, mode): 2 held, 1 put away
    send_held = 0xC008B0,  -- (peer, avatar entity, item, mode): rpc_set_held_carryable, peer -2 = everyone
}
-- The first 16 bytes of each function, checked once per session before anything is called.
Holster.PROLOGUES = {set_item = '48895c241848894c2408555657415441', set_mode = '48895c24204489442418555657415441',
                     send_held = '48895c241044894c2420574883ec6048'}
local OWNER_NETWORK_MAP, OWNER_ENTITY_MAP, OWNER_RECORDS, OWNER_SETTINGS = 0xF24990, 0xF1C978, 0xF349E0, 0xF14688
local AVATAR_TYPE_LOW, AVATAR_TYPE_HIGH = 0x294DFA97, 0x4D1C334D -- content/fac_helldivers/cha_avatar/avatar_helldiver
local INPUT_SLOTS, INPUT_STRIDE, BACKPACK_FUNCTION = 0x150 + 0x1B68, 0xA7AEC, 37
local ROW_SIZE, SETTINGS_SLOTS, SETTINGS_SIZE = 48, 702, 232
local TYPE_OFFSET, ONE_HANDED_OFFSET = 0x80, 0xC4
Holster.SHIELD_TYPE = 25        -- EquipmentType_BackpackShield
Holster.CHECK_FRAMES = 30       -- the kept addresses are checked on every 30th frame
Holster.RESTOW_LIMIT = 6        -- re-stows within RESTOW_WINDOW frames before the addon gives up the toggle
Holster.RESTOW_WINDOW = 120
local MODE_HELD, MODE_AWAY = 2, 1
local HIGH = 4294967296
local POSITIVE_INFINITY_BITS = 0x7F800000

-- assert without the file:line prefix: these messages go to the user's log.
local function need(value, message)
    if not value then error(message, 0) end
    return value
end

-- (a * b) mod 2^32 for 32-bit a and b without losing bits in a double.
local function mul32(a, b)
    local high, low = math.floor(a / 65536), a % 65536
    return (high * b % 65536 * 65536 + low * b) % HIGH
end

local function valid_pointer(value)
    return value ~= nil and value >= 0x10000 and value < 0x800000000000
end

-- The row index of key in the game's open-addressed map whose 20-byte header {data, capacity, empty key,
-- multiplier} is at header, or nil. Reads the header and one 8-byte bucket per probe.
local function lookup(api, header, key, capacity_limit)
    if not api.view(header, 20) then return nil end
    local w = api.words
    local data, capacity, empty, multiplier = w[0] + w[1] * HIGH, w[2], w[3], w[4]
    if not valid_pointer(data) or capacity == 0 or capacity > capacity_limit or band(capacity, capacity - 1) ~= 0 then
        return nil
    end
    local product = mul32(key, multiplier)
    for probe = 0, math.min(capacity, 64) - 1 do
        if not api.view(data + 8 * band(product + probe, capacity - 1), 8) then return nil end
        if w[0] == key then return w[1] ~= 0xFFFFFFFF and w[1] or nil end
        if w[0] == empty then return nil end
    end
    return nil
end

-- The local player's avatar record: {address, words (6), entity}, or nil and why.
local function local_avatar(api, game)
    local L = Holster.LAYOUT
    local players, owner = api.u64(game + L.players), api.u64(game + L.owner)
    if not valid_pointer(players) or not valid_pointer(owner) then return nil, 'player manager not ready' end
    if not api.view(players + 0x84, 8) then return nil, 'player counts unreadable' end
    local total, here = api.words[0], api.words[1]
    if total < 1 or total > 4 or here < 1 or here > 4 then return nil, 'no local player' end
    if not api.view(players + 0x3A8, 4) or api.words[0] == 0x7FFF then return nil, 'no local avatar' end
    local network_id = api.words[0]
    local player = api.u64(players + 0xE8)
    if not valid_pointer(player) or not api.view(player, 24) or band(api.words[5], 1) == 0 then
        return nil, 'local player record not owned here'
    end
    local index = lookup(api, owner + OWNER_NETWORK_MAP, network_id, 1048576)
    if not index or index >= 262144 then return nil, 'avatar not in the entity map' end
    local address = owner + OWNER_RECORDS + 24 * index
    if not api.view(address, 24) then return nil, 'avatar record unreadable' end
    local w = api.words
    if w[0] ~= AVATAR_TYPE_LOW or w[1] ~= AVATAR_TYPE_HIGH or band(w[5], 1) == 0 then
        return nil, 'not an owned Helldiver avatar'
    end
    return {address = address, words = {w[0], w[1], w[2], w[3], w[4], w[5]}, entity = w[2]}
end

local function same_record(api, words)
    local w = api.words
    return w[0] == words[1] and w[1] == words[2] and w[2] == words[3] and w[3] == words[4] and w[4] == words[5]
        and w[5] == words[6]
end

-- Where the avatar sits in the avatar manager: {manager, index, entity pointer}, or nil and why.
local function avatar_slot(api, game, avatar)
    local manager = api.u64(game + Holster.LAYOUT.avatars)
    if not valid_pointer(manager) then return nil, 'avatar manager not ready' end
    local index = lookup(api, manager + 0xF8, avatar.entity, 64)
    if not index or not api.view(manager + 0x6C, 4) or api.words[0] > 8 or index >= api.words[0] then
        return nil, 'avatar not in the avatar manager'
    end
    local pointer = api.u64(manager + 0x110 + 8 * index)
    if not valid_pointer(pointer) or not api.view(pointer, 24) or not same_record(api, avatar.words) then
        return nil, 'avatar manager entry holds another entity'
    end
    return {manager = manager, index = index, pointer = pointer}
end

-- The avatar's inventory row: {inventory, index, address}, or nil and why. Its identity pointer must be the
-- avatar's own entity record (live on the ship, 2026-10-16).
local function inventory_row(api, game, avatar)
    local inventory = api.u64(game + Holster.LAYOUT.inventory)
    if not valid_pointer(inventory) then return nil, 'inventory not ready' end
    local index = lookup(api, inventory + 40, avatar.entity, 65536)
    if not index then return nil, 'no inventory row' end
    local identities, rows = api.u64(inventory + 64), api.u64(inventory + 80)
    if not valid_pointer(identities) or not valid_pointer(rows) then return nil, 'inventory arrays missing' end
    if api.u64(identities + 8 * index) ~= avatar.address then return nil, 'inventory row of another entity' end
    return {inventory = inventory, index = index, address = rows + ROW_SIZE * index}
end

-- Everything the addon keeps about the local Helldiver, found from the registry roots, or nil and why.
function Holster.resolve(api, game)
    local avatar, why = local_avatar(api, game)
    if not avatar then return nil, why end
    local slot, slot_why = avatar_slot(api, game, avatar)
    if not slot then return nil, slot_why end
    local row, row_why = inventory_row(api, game, avatar)
    if not row then return nil, row_why end
    return {avatar = avatar, manager = slot.manager, index = slot.index, pointer = slot.pointer,
            inventory = row.inventory, row_index = row.index, row = row.address,
            key = slot.manager + INPUT_SLOTS + INPUT_STRIDE * slot.index + BACKPACK_FUNCTION * 32 + 8}
end

-- Whether the kept resolution still holds: the same avatar entry and record, and the same inventory row.
function Holster.still_valid(api, game, kept)
    if api.u64(game + Holster.LAYOUT.avatars) ~= kept.manager then return false end
    if api.u64(kept.manager + 0x110 + 8 * kept.index) ~= kept.pointer then return false end
    if not api.view(kept.pointer, 24) or not same_record(api, kept.avatar.words) then return false end
    if api.u64(game + Holster.LAYOUT.inventory) ~= kept.inventory then return false end
    return lookup(api, kept.inventory + 40, kept.avatar.entity, 65536) == kept.row_index
end

-- The shared EquipmentComponent of a resource (0x508E90): 688 slots of {resource u64, index u32, pad} probed
-- linearly from resource % 688, then 232-byte records. Returns the record's address, or nil and why.
local function shared_settings(api, owner, low, high)
    local table_address = api.u64(owner + OWNER_SETTINGS)
    if not valid_pointer(table_address) then return nil, 'equipment settings not loaded' end
    local slot = (high * (HIGH % SETTINGS_SLOTS) + low) % SETTINGS_SLOTS
    for _ = 1, SETTINGS_SLOTS do
        if not api.view(table_address + 16 * slot, 12) then return nil, 'equipment settings unreadable' end
        local w = api.words
        if w[0] == low and w[1] == high then return table_address + 16 * SETTINGS_SLOTS + SETTINGS_SIZE * w[2] end
        if w[0] == 0 and w[1] == 0 then return nil, 'no equipment settings' end
        slot = (slot + 1) % SETTINGS_SLOTS
    end
    return nil, 'no equipment settings'
end

-- The 232-byte EquipmentComponent the game's getter (0x5092B0) uses for an entity: its per-entity copy, else the
-- shared settings of its resource. Returns the record's address, or nil and why.
local function equipment_record(api, game, entity)
    local L = Holster.LAYOUT
    local copies = api.u64(game + L.equipment)
    if valid_pointer(copies) then
        local index = lookup(api, copies + 80, entity, 65536)
        local records = index and api.u64(copies + 144)
        if valid_pointer(records) then return records + SETTINGS_SIZE * index end
    end
    local owner = api.u64(game + L.owner)
    if not valid_pointer(owner) then return nil, 'entities not ready' end
    local record = lookup(api, owner + OWNER_ENTITY_MAP, entity, 1048576)
    if not record or not api.view(owner + OWNER_RECORDS + 24 * record, 24) or api.words[2] ~= entity then
        return nil, 'entity ' .. entity .. ' not found'
    end
    return shared_settings(api, owner, api.words[0], api.words[1])
end

-- The entity's equipment type and one-handed flag, or nil and why.
function Holster.equipment(api, game, entity)
    local address, why = equipment_record(api, game, entity)
    if not address then return nil, nil, why end
    if not api.view(address + TYPE_OFFSET, 4) then return nil, nil, 'equipment type unreadable' end
    local kind = api.words[0]
    if not api.view(address + ONE_HANDED_OFFSET, 1) then return nil, nil, 'equipment flags unreadable' end
    return kind, api.bytes[0] ~= 0
end

-- The row's words the addon uses: backpack (+12), held carryable (+20), slot in hand (+28), carry mode (+32).
function Holster.read_row(api, address)
    if not api.view(address + 12, 24) then return nil end
    local w = api.words
    return w[0], w[2], w[4], w[5]
end

-- The entity id of the weapon in the slot in hand (1 primary, 2 sidearm, 3 support), or nil.
local function weapon_in_hand(api, row_address, slot)
    if slot < 1 or slot > 3 or not api.view(row_address + 4 * (slot - 1), 4) then return nil end
    return api.words[0]
end

local Instance = {}
Instance.__index = Instance

-- api: view/u64 reads (bytes, words) and the three native calls; game: game.dll's base; note(line): the log.
function Holster.new(api, game, note)
    local self = setmetatable({api = api, game = game, note = note, frame = 0, kept = nil, backpack = nil,
                               shield = false, toggled = false, toggled_for = nil, key_bits = 0, pending = nil,
                               restows = {}, nones = {}, counts = {presses = 0, holsters = 0, draws = 0,
                               restows = 0, checked = 0, failed = 0, refused = 0}}, Instance)
    self.step = function() return self:frame_step() end
    return self
end

function Instance:read_nones()
    local L, api = Holster.LAYOUT, self.api
    local item = api.view(self.game + L.none_item, 4) and api.words[0] or 0
    local slot = api.view(self.game + L.none_slot, 4) and api.words[0] or 0
    self.nones = {[0] = true, [item] = true, [slot] = true}
    self.none_item = item
end

function Instance:is_none(id) return self.nones[id] == true end

function Instance:forget(reason)
    if self.toggled then self:untoggle(reason) end
    self.kept, self.backpack, self.shield, self.key_bits, self.pending = nil, nil, false, 0, nil
end

function Instance:untoggle(reason)
    self.toggled, self.toggled_for = false, nil
    if reason then self.note('Shield toggle off: ' .. reason .. '.') end
end

-- A full resolution from the registry roots; keeps it. Returns it, or nil and why.
function Instance:resolve()
    local kept, why = Holster.resolve(self.api, self.game)
    if not kept then return nil, why end
    if self.kept == nil or self.kept.avatar.entity ~= kept.avatar.entity then
        if self.toggled then self:untoggle('a new Helldiver') end
        self.backpack, self.shield, self.key_bits = nil, false, 0
        if kept.avatar.entity ~= self.last_avatar then
            self.last_avatar = kept.avatar.entity
            self.note(format('Found your Helldiver (avatar %d, inventory row %d).', kept.avatar.entity, kept.row_index))
        end
    end
    self.kept = kept
    return kept
end

-- The backpack changed: is the new one a shield? (its settings, read once per backpack id)
function Instance:backpack_changed(backpack)
    if self.toggled then self:untoggle('the backpack changed') end
    self.backpack, self.shield, self.key_bits = backpack, false, 0
    if self:is_none(backpack) then return end
    local kind = Holster.equipment(self.api, self.game, backpack)
    self.shield = kind == Holster.SHIELD_TYPE
    if self.shield then self.note(format('Shield backpack %d worn: Backpack Function toggles it.', backpack)) end
end

-- The three calls of one move, exactly as the game makes them, then the check on the next frame.
function Instance:move(kept, shield, mode, label)
    local api, avatar = self.api, kept.avatar.entity
    api.set_item(kept.inventory, avatar, mode == MODE_HELD and shield or self.none_item)
    api.set_mode(kept.inventory, avatar, mode)
    api.send_held(-2, avatar, shield, mode)
    self.pending = {mode = mode, shield = shield, label = label}
    local count = mode == MODE_HELD and 'draws' or 'holsters'
    self.counts[count] = self.counts[count] + 1
end

-- The check of the last move: the row must show it. A draw holds the shield in mode 2. A stow leaves nothing
-- held, and with nothing held 0x9AC8E0 writes carry mode 0 whatever mode it was given.
function Instance:check_move(held, mode)
    local pending = self.pending
    self.pending = nil
    local ok
    if pending.mode == MODE_HELD then
        ok = held == pending.shield and mode == MODE_HELD
    else
        ok = self:is_none(held)
    end
    self.counts[ok and 'checked' or 'failed'] = self.counts[ok and 'checked' or 'failed'] + 1
    self.note(format('%s: %s (held %d, mode %d).', pending.label, ok and 'done' or 'FAILED, the game did not take it',
                     held, mode))
end

-- Before any move: everything found again from the roots, the backpack still a shield. Returns the fresh
-- resolution and the row's words, or nil and why.
function Instance:verified(shield)
    local kept, why = self:resolve()
    if not kept then return nil, why end
    local backpack, held, slot, mode = Holster.read_row(self.api, kept.row)
    if backpack == nil then return nil, 'inventory row unreadable' end
    if backpack ~= shield then return nil, 'the backpack changed' end
    local kind, _, kind_why = Holster.equipment(self.api, self.game, backpack)
    if kind ~= Holster.SHIELD_TYPE then return nil, kind_why or 'the backpack is not a shield' end
    return kept, held, slot, mode
end

function Instance:refuse(what, why)
    self.counts.refused = self.counts.refused + 1
    self.note(what .. ' refused: ' .. tostring(why) .. '.')
end

-- A press of Backpack Function while a shield backpack is worn.
function Instance:press(shield)
    self.counts.presses = self.counts.presses + 1
    local kept, held, slot, mode = self:verified(shield)
    if not kept then return self:refuse('Press', held) end
    if held == shield then
        self.toggled, self.toggled_for = true, kept.avatar.entity
        return self:move(kept, shield, MODE_AWAY, 'Shield to the back')
    end
    if not self:is_none(held) then
        self.toggled = not self.toggled
        self.toggled_for = self.toggled and kept.avatar.entity or nil
        return self.note(format('Press while carrying something else: the shield %s.',
                                self.toggled and 'stays on the back' or 'returns with the next one-handed weapon'))
    end
    if not self.toggled then
        self.toggled, self.toggled_for = true, kept.avatar.entity
        return self.note('Press with the shield on the back: it stays there.')
    end
    self:untoggle()
    local weapon = weapon_in_hand(self.api, kept.row, slot)
    local one_handed = weapon and select(2, Holster.equipment(self.api, self.game, weapon))
    if one_handed then return self:move(kept, shield, MODE_HELD, 'Shield to the hand') end
    self.note('Shield toggle off: it returns with the next one-handed weapon.')
end

-- The game drew the shield while the toggle is on: stow it again, unless that keeps happening.
function Instance:restow(shield)
    local restows, frame = self.restows, self.frame
    while restows[1] and frame - restows[1] >= Holster.RESTOW_WINDOW do table.remove(restows, 1) end
    if #restows >= Holster.RESTOW_LIMIT then
        self.restows = {}
        return self:untoggle(format('the game drew the shield %d times in %d frames, so it stays in hand',
                                    Holster.RESTOW_LIMIT + 1, Holster.RESTOW_WINDOW))
    end
    local kept, held = self:verified(shield)
    if not kept then return self:refuse('Re-stow', held) end
    if kept.avatar.entity ~= self.toggled_for then return self:untoggle('a new Helldiver') end
    if held ~= shield then return end
    restows[#restows + 1] = frame
    self.counts.restows = self.counts.restows + 1
    self:move(kept, shield, MODE_AWAY, 'Shield back to the back after the game drew it')
end

-- Action 37's held time, as its float bits: 0 when released, positive below infinity while held.
function Instance:key_pressed()
    if not self.api.view(self.kept.key, 4) then return false end
    local bits, before = self.api.words[0], self.key_bits
    self.key_bits = bits
    return before == 0 and bits > 0 and bits < POSITIVE_INFINITY_BITS
end

-- Every 30th frame: the kept addresses must still be the local Helldiver's, else find them again (the game moves
-- inventory rows when a Helldiver dies; resolve keeps the toggle while the avatar entity is the same).
function Instance:check()
    if self.kept and Holster.still_valid(self.api, self.game, self.kept) then return end
    local _, why = self:resolve()
    if why and self.kept then self:forget('the Helldiver is gone (' .. why .. ')') end
end

-- One frame with a kept resolution: the row read, then the key read while a shield backpack is worn. Another
-- backpack at the kept row may only mean the game moved the rows (it does when a Helldiver dies): the row is
-- found again from the registries before the change counts.
function Instance:watch(kept)
    local backpack, held, _, mode = Holster.read_row(self.api, kept.row)
    if backpack ~= self.backpack and self.backpack ~= nil then
        kept = self:resolve()
        if not kept then return self:forget('the Helldiver is gone') end
        backpack, held, _, mode = Holster.read_row(self.api, kept.row)
    end
    if backpack == nil then return self:forget('the inventory row went away') end
    if self.pending then self:check_move(held, mode) end
    if backpack ~= self.backpack then self:backpack_changed(backpack) end
    if not self.shield then return end
    if self:key_pressed() then return self:press(backpack) end
    if self.toggled and held == backpack then self:restow(backpack) end
end

-- The per-frame step: one row read; a key read while a shield is worn; the rest only when something happens.
function Instance:frame_step()
    local frame = self.frame + 1
    self.frame = frame
    if self.kept then self:watch(self.kept) end
    if frame % Holster.CHECK_FRAMES == 0 then self:check() end
end

function Instance:summary()
    local c = self.counts
    return format('presses %d, to the back %d (re-stows %d), to the hand %d, checks done %d, failed %d, refused %d',
                  c.presses, c.holsters, c.restows, c.draws, c.checked, c.failed, c.refused)
end

-- The guard's pause (an update below failed): start afresh; the shield stays where the game has it.
function Instance:pause(reason)
    self:forget()
    self.note('Paused (' .. tostring(reason) .. ').')
end

function Instance:stopped(reason)
    self.note('Stopped (' .. tostring(reason) .. '): ' .. self:summary() .. '.')
end

-- The in-game adapter: the Windows calls and the game's functions, declared under private names (an __asm__
-- label naming the real export, private typedefs for the game's function pointers), so another mod's
-- declarations neither change these calls nor are changed by them. Addresses go in as uint64_t numbers. view
-- reads into one reused buffer (bytes and 32-bit words), u64 into two reused words: no allocation per read.
local DECLARATIONS = [[
void *hys1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
int hys1_ReadProcessMemory(void *process, uint64_t address, void *buffer, size_t size, uint32_t *done) __asm__("ReadProcessMemory");
typedef void (*hys1_set_item)(uint64_t inventory, uint32_t avatar, uint32_t item);
typedef uint64_t (*hys1_set_mode)(uint64_t inventory, uint32_t avatar, uint32_t mode);
typedef void (*hys1_send_held)(int64_t peer, uint32_t avatar, uint32_t item, uint32_t mode);
]]

function Holster.adapter()
    need(ffi.abi('64bit'), 'Windows x64 is required')
    if not pcall(ffi.typeof, 'hys1_set_item') then ffi.cdef(DECLARATIONS) end
    local kernel = ffi.load('kernel32')
    local process, read_memory = kernel.hys1_GetCurrentProcess(), kernel.hys1_ReadProcessMemory
    local done, pair = ffi.new('uint32_t[2]'), ffi.new('uint32_t[2]')
    local view_size = 64
    local view = ffi.new('uint8_t[?]', view_size)
    local api = {bytes = view, words = ffi.cast('uint32_t *', view)}

    function api.view(address, size)
        if size < 1 or size > view_size then return false end
        return read_memory(process, address, view, size, done) ~= 0 and done[0] == size and done[1] == 0
    end

    function api.u64(address)
        if read_memory(process, address, pair, 8, done) == 0 or done[0] ~= 8 or done[1] ~= 0 then return nil end
        return pair[0] + pair[1] * HIGH
    end

    -- Binds the game's three functions after checking their first bytes; raises when one differs.
    function api.bind(game)
        local L = Holster.LAYOUT
        for name, expected in pairs(Holster.PROLOGUES) do
            need(api.view(game + L[name], 16), 'game function unreadable: ' .. name)
            local got = {}
            for i = 0, 15 do got[#got + 1] = format('%02x', view[i]) end
            need(table.concat(got) == expected, 'game function differs: ' .. name)
        end
        local set_item = ffi.cast('hys1_set_item', game + L.set_item)
        local set_mode = ffi.cast('hys1_set_mode', game + L.set_mode)
        local send_held = ffi.cast('hys1_send_held', game + L.send_held)
        api.set_item = function(inventory, avatar, item) set_item(inventory, avatar, item) end
        api.set_mode = function(inventory, avatar, mode) set_mode(inventory, avatar, mode) end
        api.send_held = function(peer, avatar, item, mode) send_held(peer, avatar, item, mode) end
    end

    return api
end

-- Bingus Shared Loader v18+ with API 1, recognized by what it offers, never by its internal version.
function Holster.loader_ok(loader)
    return type(loader) == 'table' and loader.api == 1 and type(loader.open_log) == 'function'
end

-- Everything stays interpreted, the per-frame row and key reads included: they are two calls and a few
-- comparisons, and kept out of the compiler they add no trace to the LuaJIT code cache the game and every mod
-- share (512 KB and 1000 traces unless the loader raises them). Only the step's entry is left on, as in Laser
-- Sentry Cooldown; a trace through it stops at the first interpreted call.
local HELPERS = {need, mul32, valid_pointer, lookup, local_avatar, same_record, avatar_slot, inventory_row,
                 shared_settings, equipment_record, weapon_in_hand}
local function interpreted(functions)
    if type(jit) ~= 'table' or type(jit.off) ~= 'function' then return end
    for _, fn in pairs(functions) do
        if type(fn) == 'function' then pcall(jit.off, fn, true) end
    end
end
interpreted({interpreted})
function Holster.interpreted_but_step(instance)
    interpreted(HELPERS)
    interpreted(Holster)
    interpreted(Instance)
    interpreted(instance.api)
    interpreted({instance.note})
    if type(jit) == 'table' and type(jit.on) == 'function' then pcall(jit.on, instance.step) end
end

-- Builds the instance and installs Bingus Shared Runtime's update guard (bingus_runtime.lua, bundled by the
-- build): the previous update runs outside pcall, 8 errors in a burst stop the addon, an error below pauses it
-- until the updates below run cleanly for 60 frames, and the first failure survives shutdown. options.adapter
-- replaces the in-game adapter and options.env the global table (tests). Returns the instance, or nil when
-- disabled.
function Holster.install(runtime, memory, options)
    options = options or {}
    local loader = rawget(_G, 'CowboyBingusModLoader')
    local log_file
    if loader and type(loader.open_log) == 'function' then
        pcall(function() log_file = loader.open_log('HolsterYourShield.log') end)
    end
    local function note(line)
        print('[HolsterYourShield] ' .. line)
        if log_file then pcall(function() log_file:write(line .. '\n'); log_file:flush() end) end
    end
    local ready, instance = pcall(function()
        need(Holster.loader_ok(loader), 'Bingus Shared Loader v18+ / API 1 required')
        local game = memory.module('game.dll')
        need(game ~= nil and memory.module(nil) ~= nil, 'game modules unavailable')
        local ok, why = memory.verify_build({exe_sha256 = Holster.EXE_SHA256, game_sha256 = Holster.GAME_SHA256})
        need(ok, why == 'unsupported game build' and 'unsupported game build (needs Steam build 26088801)'
             or tostring(why))
        local api = (options.adapter or Holster.adapter)()
        local base = memory.address(game)
        api.bind(base)
        local made = Holster.new(api, base, note)
        made:read_nones()
        return made
    end)
    if not ready then
        note('Disabled: ' .. tostring(instance))
        return nil
    end
    Holster.interpreted_but_step(instance)
    local env = options.env or _G
    local guard = runtime.guard({name = 'HolsterYourShield', step = instance.step,
                                 stop = function(reason) instance:stopped(reason) end,
                                 pause = function(reason) instance:pause(reason) end,
                                 log = note, env = env}).install()
    instance.guard, instance.env = guard, env
    rawset(env, 'HolsterYourShieldInstalled', true)
    note('Holster Your Shield ' .. Holster.REVISION .. ' initialized (loader API ' .. tostring(loader.api) .. ').')
    return instance
end

return Holster
end)()
Holster.install(bingus_runtime, bingus_memory.new(bingus_runtime))
